import { Injectable } from '@angular/core';
import {
  CanActivate,
  ActivatedRouteSnapshot,
  RouterStateSnapshot,
  Router,
} from '@angular/router';
import { Observable } from 'rxjs';
import { AuthService } from '../services/auth.service';

@Injectable({
  providedIn: 'root',
})
export class PermissionGuard implements CanActivate {
  constructor(private authService: AuthService, private router: Router) {}

  canActivate(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): Observable<boolean> | Promise<boolean> | boolean {
    // Check if user is authenticated
    if (!this.authService.isAuthenticated()) {
      this.router.navigate(['/login']);
      return false;
    }

    // Get the required permission from route data
    const requiredPermission = route.data['permission'];

    // If no permission is required, allow access
    if (!requiredPermission) {
      return true;
    }

    // Check if user has the required permission
    const hasPermission = this.authService.hasPermission(requiredPermission);

    if (!hasPermission) {
      // تحقق مرة أخرى من الـ authentication
      // لأن hasPermission قد يكون عمل clearAuth() لو التوكن منتهي
      if (!this.authService.isAuthenticated()) {
        this.router.navigate(['/login']);
        return false;
      }
      // المستخدم مُصادق عليه لكن مش عنده الصلاحية
      this.router.navigate(['/unauthorized']);
      return false;
    }

    return true;
  }
}
